WITH not_flagged AS (SELECT s.* FROM departments s WHERE EXISTS (SELECT 1 FROM employees c WHERE c.dept_id = s.id AND NOT c.is_remote)) SELECT CASE WHEN budget >= 4124000 THEN 'HIGH' ELSE 'LOW' END AS budget_tier, SUM(CASE WHEN dept_name = 'Finance' THEN budget ELSE 0 END) AS finance_budget, STDDEV_SAMP(budget) AS budget_stddev, SUM(CASE WHEN dept_name = 'Sales' THEN budget ELSE 0 END) AS sales_budget FROM not_flagged GROUP BY CUBE (CASE WHEN budget >= 4124000 THEN 'HIGH' ELSE 'LOW' END) ORDER BY budget_stddev DESC;
